B.aeP=new A.t("\u0421\u0438\u043b\u044c\u043d\u044b\u0439 \u043d\u0435 \u0442\u043e\u0442, \u043a\u0442\u043e \u043e\u0434\u043e\u043b\u0435\u0432\u0430\u0435\u0442 \u0434\u0440\u0443\u0433\u0438\u0445 \u0432 \u0431\u043e\u0440\u044c\u0431\u0435, \u0430 \u0442\u043e\u0442, \u043a\u0442\u043e \u0432\u043b\u0430\u0434\u0435\u0435\u0442 \u0441\u043e\u0431\u043e\u0439 \u0432 \u0433\u043d\u0435\u0432\u0435.","\u0411\u0443\u0445\u0430\u0440\u0438, \u041c\u0443\u0441\u043b\u0438\u043c")
B.ady=new A.t("\u041d\u0435 \u0431\u043b\u0430\u0433\u043e\u0434\u0430\u0440\u0438\u0442 \u0410\u043b\u043b\u0430\u0445\u0430 \u0442\u043e\u0442, \u043a\u0442\u043e \u043d\u0435 \u0431\u043b\u0430\u0433\u043e\u0434\u0430\u0440\u0438\u0442 \u043b\u044e\u0434\u0435\u0439.","\u0410\u0431\u0443 \u0414\u0430\u0443\u0434, \u0422\u0438\u0440\u043c\u0438\u0437\u0438")
B.aeq=new A.t("\u0410\u043b\u043b\u0430\u0445 \u043d\u0435 \u0441\u043c\u043e\u0442\u0440\u0438\u0442 \u043d\u0430 \u0432\u0430\u0448 \u043e\u0431\u043b\u0438\u043a \u0438 \u0432\u0430\u0448\u0435 \u0438\u043c\u0443\u0449\u0435\u0441\u0442\u0432\u043e, \u043d\u043e \u0441\u043c\u043e\u0442\u0440\u0438\u0442 \u043d\u0430 \u0432\u0430\u0448\u0438 \u0441\u0435\u0440\u0434\u0446\u0430 \u0438 \u0432\u0430\u0448\u0438 \u0434\u0435\u043b\u0430.","\u041c\u0443\u0441\u043b\u0438\u043c")
B.aei=new A.t("\u041c\u0438\u043b\u043e\u0441\u0435\u0440\u0434\u043d\u044b\u043c \u043e\u043a\u0430\u0436\u0435\u0442 \u043c\u0438\u043b\u043e\u0441\u0442\u044c \u041c\u0438\u043b\u043e\u0441\u0442\u0438\u0432\u044b\u0439. \u0411\u0443\u0434\u044c\u0442\u0435 \u043c\u0438\u043b\u043e\u0441\u0435\u0440\u0434\u043d\u044b \u043a \u0442\u0435\u043c, \u043a\u0442\u043e \u043d\u0430 \u0437\u0435\u043c\u043b\u0435, \u2014 \u0438 \u0431\u0443\u0434\u0435\u0442 \u043c\u0438\u043b\u043e\u0441\u0435\u0440\u0434\u0435\u043d \u043a \u0432\u0430\u043c \u0422\u043e\u0442, \u041a\u0442\u043e \u043d\u0430 \u043d\u0435\u0431\u0435\u0441\u0430\u0445.","\u0410\u0431\u0443 \u0414\u0430\u0443\u0434, \u0422\u0438\u0440\u043c\u0438\u0437\u0438")
B.adq=new A.t("\u0422\u043e\u043c\u0443, \u043a\u0442\u043e \u0443\u043a\u0430\u0437\u0430\u043b \u043d\u0430 \u0431\u043b\u0430\u0433\u043e\u0435, \u2014 \u043d\u0430\u0433\u0440\u0430\u0434\u0430, \u043a\u0430\u043a \u0441\u043e\u0432\u0435\u0440\u0448\u0438\u0432\u0448\u0435\u043c\u0443 \u0435\u0433\u043e.","\u041c\u0443\u0441\u043b\u0438\u043c")
B.afb=new A.t("\u041e\u0431\u043b\u0435\u0433\u0447\u0430\u0439\u0442\u0435 \u0438 \u043d\u0435 \u0437\u0430\u0442\u0440\u0443\u0434\u043d\u044f\u0439\u0442\u0435, \u0440\u0430\u0434\u0443\u0439\u0442\u0435 \u0438 \u043d\u0435 \u043e\u0442\u0442\u0430\u043b\u043a\u0438\u0432\u0430\u0439\u0442\u0435.","\u0411\u0443\u0445\u0430\u0440\u0438, \u041c\u0443\u0441\u043b\u0438\u043c")
B.ach=new A.t("\u041c\u0443\u0441\u0443\u043b\u044c\u043c\u0430\u043d\u0438\u043d \u2014 \u0442\u043e\u0442, \u043e\u0442 \u044f\u0437\u044b\u043a\u0430 \u0438 \u0440\u0443\u043a \u043a\u043e\u0442\u043e\u0440\u043e\u0433\u043e \u0432 \u0431\u0435\u0437\u043e\u043f\u0430\u0441\u043d\u043e\u0441\u0442\u0438 \u0434\u0440\u0443\u0433\u0438\u0435 \u043c\u0443\u0441\u0443\u043b\u044c\u043c\u0430\u043d\u0435.","\u0411\u0443\u0445\u0430\u0440\u0438, \u041c\u0443\u0441\u043b\u0438\u043c")
B.acc=new A.t("\u0415\u0441\u0442\u044c \u0434\u0432\u0435 \u043c\u0438\u043b\u043e\u0441\u0442\u0438, \u0432 \u043a\u043e\u0442\u043e\u0440\u044b\u0445 \u043c\u043d\u043e\u0433\u0438\u0435 \u043b\u044e\u0434\u0438 \u0442\u0435\u0440\u043f\u044f\u0442 \u0443\u0431\u044b\u0442\u043e\u043a: \u0437\u0434\u043e\u0440\u043e\u0432\u044c\u0435 \u0438 \u0441\u0432\u043e\u0431\u043e\u0434\u043d\u043e\u0435 \u0432\u0440\u0435\u043c\u044f.","\u0411\u0443\u0445\u0430\u0440\u0438")
B.adO=new A.t("\u0411\u0443\u0434\u044c \u0432 \u044d\u0442\u043e\u043c \u043c\u0438\u0440\u0435 \u0441\u043b\u043e\u0432\u043d\u043e \u0447\u0443\u0436\u0435\u0437\u0435\u043c\u0435\u0446 \u0438\u043b\u0438 \u043f\u0443\u0442\u043d\u0438\u043a.","\u0411\u0443\u0445\u0430\u0440\u0438")
B.aed=new A.t("\u041f\u043e\u0438\u0441\u0442\u0438\u043d\u0435, \u0410\u043b\u043b\u0430\u0445 \u043c\u044f\u0433\u043e\u043a \u0438 \u043b\u044e\u0431\u0438\u0442 \u043c\u044f\u0433\u043a\u043e\u0441\u0442\u044c \u0432\u043e \u0432\u0441\u0435\u0445 \u0434\u0435\u043b\u0430\u0445.","\u0411\u0443\u0445\u0430\u0440\u0438, \u041c\u0443\u0441\u043b\u0438\u043c")
B.aeY=new A.t("\u0422\u043e\u043c\u0443, \u043a\u0442\u043e \u0432\u0441\u0442\u0430\u043d\u0435\u0442 \u043d\u0430 \u043f\u0443\u0442\u044c \u043f\u043e\u0438\u0441\u043a\u0430 \u0437\u043d\u0430\u043d\u0438\u044f, \u0410\u043b\u043b\u0430\u0445 \u043e\u0431\u043b\u0435\u0433\u0447\u0438\u0442 \u043f\u0443\u0442\u044c \u0432 \u0420\u0430\u0439.","\u041c\u0443\u0441\u043b\u0438\u043c")
B.aeB=new A.t("\u0421\u0430\u0434\u0430\u043a\u0430 \u043d\u0435 \u0443\u043c\u0435\u043d\u044c\u0448\u0430\u0435\u0442 \u0438\u043c\u0443\u0449\u0435\u0441\u0442\u0432\u0430.","\u041c\u0443\u0441\u043b\u0438\u043c")
B.acj=new A.t("\u0421\u0430\u043c\u044b\u0435 \u0441\u043e\u0432\u0435\u0440\u0448\u0435\u043d\u043d\u044b\u0435 \u043f\u043e \u0432\u0435\u0440\u0435 \u0441\u0440\u0435\u0434\u0438 \u0432\u0435\u0440\u0443\u044e\u0449\u0438\u0445 \u2014 \u043b\u0443\u0447\u0448\u0438\u0435 \u0438\u0437 \u043d\u0438\u0445 \u043f\u043e \u043d\u0440\u0430\u0432\u0443.","\u0410\u0431\u0443 \u0414\u0430\u0443\u0434, \u0422\u0438\u0440\u043c\u0438\u0437\u0438")
