B.abL=new A.t("\u041d\u0430\u043c\u0430\u0437 \u0432 \u043e\u0431\u0449\u0438\u043d\u0435 \u043f\u0440\u0435\u0432\u043e\u0441\u0445\u043e\u0434\u0438\u0442 \u043d\u0430\u043c\u0430\u0437 \u0432 \u043e\u0434\u0438\u043d\u043e\u0447\u043a\u0443 \u043d\u0430 \u0434\u0432\u0430\u0434\u0446\u0430\u0442\u044c \u0441\u0435\u043c\u044c \u0441\u0442\u0435\u043f\u0435\u043d\u0435\u0439.","\u0411\u0443\u0445\u0430\u0440\u0438, \u041c\u0443\u0441\u043b\u0438\u043c")
B.acx=new A.t("\u0422\u043e\u043c\u0443, \u043a\u0442\u043e \u043f\u043e\u0441\u0442\u0438\u043b\u0441\u044f \u0432 \u0420\u0430\u043c\u0430\u0434\u0430\u043d \u0441 \u0432\u0435\u0440\u043e\u0439 \u0438 \u043d\u0430\u0434\u0435\u0436\u0434\u043e\u0439 \u043d\u0430 \u043d\u0430\u0433\u0440\u0430\u0434\u0443 \u0410\u043b\u043b\u0430\u0445\u0430, \u043f\u0440\u043e\u0449\u0430\u044e\u0442\u0441\u044f \u0435\u0433\u043e \u043f\u0440\u0435\u0436\u043d\u0438\u0435 \u0433\u0440\u0435\u0445\u0438.","\u0411\u0443\u0445\u0430\u0440\u0438, \u041c\u0443\u0441\u043b\u0438\u043c")
B.acA=new A.t("\u0410\u043b\u043b\u0430\u0445 \u0412\u0441\u0435\u0432\u044b\u0448\u043d\u0438\u0439 \u0433\u043e\u0432\u043e\u0440\u0438\u0442: \xab\u042f \u2014 \u0442\u0430\u043a\u043e\u0432, \u043a\u0430\u043a\u0438\u043c \u041c\u043e\u0439 \u0440\u0430\u0431 \u043f\u0440\u0435\u0434\u0441\u0442\u0430\u0432\u043b\u044f\u0435\u0442 \u041c\u0435\u043d\u044f, \u0438 \u042f \u0441 \u043d\u0438\u043c, \u043a\u043e\u0433\u0434\u0430 \u043e\u043d \u043f\u043e\u043c\u0438\u043d\u0430\u0435\u0442 \u041c\u0435\u043d\u044f\xbb.","\u0411\u0443\u0445\u0430\u0440\u0438, \u041c\u0443\u0441\u043b\u0438\u043c")
B.adr=new A.t("\u0422\u043e\u0442, \u043a\u0442\u043e \u043f\u043e\u043c\u0438\u043d\u0430\u0435\u0442 \u0441\u0432\u043e\u0435\u0433\u043e \u0413\u043e\u0441\u043f\u043e\u0434\u0430, \u0438 \u0442\u043e\u0442, \u043a\u0442\u043e \u043d\u0435 \u043f\u043e\u043c\u0438\u043d\u0430\u0435\u0442, \u043f\u043e\u0434\u043e\u0431\u043d\u044b \u0436\u0438\u0432\u043e\u043c\u0443 \u0438 \u043c\u0451\u0440\u0442\u0432\u043e\u043c\u0443.","\u0411\u0443\u0445\u0430\u0440\u0438")
B.aet=new A.t("\u0412\u0441\u0435 \u0441\u044b\u043d\u043e\u0432\u044c\u044f \u0410\u0434\u0430\u043c\u0430 \u043e\u0448\u0438\u0431\u0430\u044e\u0442\u0441\u044f, \u0430 \u043b\u0443\u0447\u0448\u0438\u0435 \u0438\u0437 \u043e\u0448\u0438\u0431\u0430\u044e\u0449\u0438\u0445\u0441\u044f \u2014 \u0442\u0435, \u043a\u0442\u043e \u043a\u0430\u0435\u0442\u0441\u044f.","\u0422\u0438\u0440\u043c\u0438\u0437\u0438, \u0418\u0431\u043d \u041c\u0430\u0434\u0436\u0430")
B.aca=new A.t("\u0410\u043b\u043b\u0430\u0445 \u0440\u0430\u0434\u0443\u0435\u0442\u0441\u044f \u043f\u043e\u043a\u0430\u044f\u043d\u0438\u044e \u0421\u0432\u043e\u0435\u0433\u043e \u0440\u0430\u0431\u0430 \u0431\u043e\u043b\u044c\u0448\u0435, \u0447\u0435\u043c \u0440\u0430\u0434\u043e\u0432\u0430\u043b\u0441\u044f \u0431\u044b \u043f\u0443\u0442\u043d\u0438\u043a, \u043d\u0430\u0448\u0435\u0434\u0448\u0438\u0439 \u0432 \u043f\u0443\u0441\u0442\u044b\u043d\u0435 \u043f\u043e\u0442\u0435\u0440\u044f\u043d\u043d\u043e\u0433\u043e \u0432\u0435\u0440\u0431\u043b\u044e\u0434\u0430 \u0441\u043e \u0441\u0432\u043e\u0435\u0439 \u0435\u0434\u043e\u0439 \u0438 \u0432\u043e\u0434\u043e\u0439.","\u0411\u0443\u0445\u0430\u0440\u0438, \u041c\u0443\u0441\u043b\u0438\u043c")
